(function(){
  if (window.__scopeInstalled__) return;
  window.__scopeInstalled__ = true;
  var canvas = document.getElementById('cv');
  var ctx = canvas.getContext('2d');
  var uSlider = document.getElementById('uSlider'), uVal = document.getElementById('uVal');
  var fSlider = document.getElementById('fSlider'), fVal = document.getElementById('fVal');
  var out = document.getElementById('out');
  var playBtn = document.getElementById('playBtn');
  var running = true, t0 = 0;
  window.simState = { Umax: 311, f: 50, Ueff: 219.9, running: true };
  function draw(){
    var Umax = parseFloat(uSlider.value), f = parseFloat(fSlider.value);
    if (running) t0 += 0.016;
    var Ueff = Umax / Math.sqrt(2);
    window.simState.Umax = Umax; window.simState.f = f; window.simState.Ueff = Ueff;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#0b1020'; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = '#1e293b'; ctx.lineWidth = 1;
    var ox = 40, oy = 180;
    for (var gx = ox; gx <= 680; gx += 20) { ctx.beginPath(); ctx.moveTo(gx, 30); ctx.lineTo(gx, 330); ctx.stroke(); }
    for (var gy = 30; gy <= 330; gy += 20) { ctx.beginPath(); ctx.moveTo(ox, gy); ctx.lineTo(680, gy); ctx.stroke(); }
    ctx.strokeStyle = '#334155'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy); ctx.lineTo(680, oy); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ox, 30); ctx.lineTo(ox, 330); ctx.stroke();
    var xScale = f * 4;
    ctx.strokeStyle = '#fbbf24'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy - Umax * 0.5); ctx.lineTo(680, oy - Umax * 0.5); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ox, oy + Umax * 0.5); ctx.lineTo(680, oy + Umax * 0.5); ctx.stroke();
    ctx.strokeStyle = '#34d399'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(ox, oy - Ueff * 0.5); ctx.lineTo(680, oy - Ueff * 0.5); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(ox, oy + Ueff * 0.5); ctx.lineTo(680, oy + Ueff * 0.5); ctx.stroke();
    ctx.strokeStyle = '#22d3ee'; ctx.lineWidth = 3;
    ctx.beginPath();
    for (var x = ox; x <= 680; x += 2) {
      var phase = (x - ox) / xScale * Math.PI * 2 - t0 * f;
      var y = oy - Umax * 0.5 * Math.sin(phase);
      if (x === ox) ctx.moveTo(x, y); else ctx.lineTo(x, y);
    }
    ctx.stroke();
    ctx.fillStyle = '#94a3b8'; ctx.font = '12px sans-serif'; ctx.textAlign = 'right';
    ctx.fillText('u(t) = Umax.sin(2π.f.t)', 676, 44);
    ctx.fillStyle = '#fbbf24'; ctx.fillText('+Umax', 660, oy - Umax * 0.5 + 14);
    ctx.fillStyle = '#34d399'; ctx.fillText('+Ueff', 660, oy - Ueff * 0.5 + 14);
    uVal.textContent = Umax.toFixed(0); fVal.textContent = f.toFixed(0);
    out.textContent = 'Ueff = Umax/√2 = ' + Umax.toFixed(0) + '/1.414 = ' + Ueff.toFixed(1) + ' V';
    window.simState.time = t0;
  }
  function loop(){ draw(); requestAnimationFrame(loop); }
  playBtn.addEventListener('click', function(){ running = !running; window.simState.running = running; playBtn.textContent = running ? 'إيقاف المسح' : 'تشغيل المسح'; });
  function fit(){ canvas.style.maxWidth = '100%'; }
  if (!window.__fitInstalled__) { fit(); window.addEventListener('resize', fit); window.__fitInstalled__ = true; }
  loop();
})();
